export function loadoutSlots(rank: Rank): number { return rank === 'Genin' ? 3 : rank === 'Chuunin' ? 4 : rank === 'Jounin' ? 5 : 0; }
export function trainingCeiling(rank: Rank, specialty?: Attribute, attribute?: Attribute): number { const base = rank === 'Academy' ? 6 : rank === 'Genin' ? 8 : rank === 'Chuunin' ? 10 : 12; return base + Number(Boolean(specialty && specialty === attribute)); }
export function developmentPlan(rank: Rank) { return { phase: rank, focus: [] as Attribute[], sessions: 0, limit: rank === 'Academy' ? 5 : rank === 'Genin' ? 6 : rank === 'Chuunin' ? 7 : rank === 'Jounin' ? 8 : 0 }; }
