    if (discipline === 'vanguard') { tags.add('offense'); tags.add('mobility'); }
    if (discipline === 'shadow-runner') { tags.add('stealth'); tags.add('mobility'); }
    if (discipline === 'tactician') { tags.add('control'); tags.add('support'); }
    if (discipline === 'ironhand') { tags.add('offense'); tags.add('defense'); }
