    if (['ice-release', 'storm-release', 'wind-style', 'lightning-style'].includes(state.character.bloodline ?? '')) { tags.add('mobility'); tags.add('perception'); }
    if (['crystal-release', 'magnet-release'].includes(state.character.bloodline ?? '')) { tags.add('defense'); tags.add('perception'); }
    if (['yin-yang-release', 'water-style', 'boil-release'].includes(state.character.bloodline ?? '')) { tags.add('support'); tags.add('control'); }
    if (['lava-release', 'scorch-release', 'explosion-release', 'fire-style'].includes(state.character.bloodline ?? '')) { tags.add('offense'); tags.add('control'); }
