    [name, rng] = shinobiName(rng); [ageRoll, rng] = roll(rng, maxAge - minAge + 1); [overallRoll, rng] = roll(rng, 18); [profileRoll, rng] = roll(rng, profiles.length); [formRoll, rng] = roll(rng, 4); [experienceRoll, rng] = roll(rng, 4);
