  if (has('mobility') && has('stealth')) synergies.push('Mobilidade + furtividade: reposiciona sem entregar a intenção.');
  if (has('offense') && has('control')) synergies.push('Ofensiva + controle: força uma resposta e limita para onde ela pode ir.');
