function summonArcEntry(id: string, summonName: string, stage: 'first' | 'second' | 'final'): [string, string, string, number, string] {
  const identity: Record<string, [string, string, string]> = {
    'corvid-contract': ['Vigias de Pena', 'seguem uma rede de informantes que só existe enquanto seus segredos não se tornam moeda pública.', 'Os corvos trouxeram uma verdade que pode comprometer a própria fonte.'],
    'hounds-contract': ['A Caçada sem Presa', 'sigam um rastro que termina em inocentes usados para encobrir quem realmente fugiu.', 'Os cães querem resposta direta; o campo exige discriminação.'],
    'moth-contract': ['Luz que Não Denuncia', 'protejam uma rota noturna sem transformar quem busca abrigo em isca visível.', 'As mariposas cobrem o caminho, mas só você decide quem merece saber dele.'],
    'boar-contract': ['Solo Jurado', 'defendam uma comunidade cuja terra é a última peça de um pacto antigo.', 'Os javalis sustentam a linha; permanecer nela terá custo político.'],
    'toad-contract': ['Mapa sob a Água', 'resolvam uma disputa de rotas onde a passagem mais eficiente atravessa uma promessa esquecida.', 'Os sapos conhecem a saída; querem saber o que você fará com quem ficou para trás.']
  };
  const [title, objective, intel] = identity[id] ?? ['Dívida do Contrato', 'honrem uma obrigação que ninguém pode resolver por força.', 'O contrato sabe mais do que contou.'];
  if (stage === 'first') return [`${title}: Primeiro Chamado`, `Com ${summonName}, ${objective}`, intel, 410, 'Contract arc: reciprocal obligation'];
  if (stage === 'second') return [`${title}: Conselho`, `Represente ${summonName} e ${objective}`, `${intel} Agora o contrato avaliará sua decisão, não sua obediência.`, 700, 'Contract arc: earned alliance'];
  return [`${title}: Juramento Final`, `Em uma crise S-rank, ${objective}`, `${intel} O contrato seguirá sua decisão uma vez e lembrará do motivo.`, 1080, 'Contract finale: chosen loyalty'];
}
